<?php
namespace AppBancos\Application;
use AppBancos\Repository\ReglaAsignacionRepository;use InvalidArgumentException;
final class RetirarReglaAsignacion{private$r;private$e;public function __construct(ReglaAsignacionRepository$r,EjecutorComandoIdempotente$e){$this->r=$r;$this->e=$e;}public function ejecutar(array$i,$op,$clave){$c=$this->id($i['configuracion_id']??null,'configuracion_id');$rid=$this->id($i['regla_asignacion_id']??null,'regla_asignacion_id');$m=trim((string)($i['motivo']??''));if(mb_strlen($m,'UTF-8')<3||mb_strlen($m,'UTF-8')>200){throw new InvalidArgumentException('motivo debe contener entre 3 y 200 caracteres.');}$x=['configuracion_id'=>$c,'regla_asignacion_id'=>$rid,'motivo'=>$m];return$this->e->ejecutar('configuracion.retirar-asignacion',$clave,$op,$x,['accion'=>'CONFIGURACION_RETIRAR_ASIGNACION','recurso_tipo'=>'REGLA_ASIGNACION','recurso_id'=>$rid,'resultado'=>'EXITOSA','detalles'=>['motivo'=>$m]],function()use($x,$op){return['codigo_http'=>200,'respuesta'=>$this->r->retirar($x['configuracion_id'],$x['regla_asignacion_id'],$op)];});}private function id($v,$c){$v=trim((string)$v);if(!preg_match('/^[0-9]{1,20}$/',$v)||($v=ltrim($v,'0'))===''){throw new InvalidArgumentException($c.' es invalido.');}return$v;}}
